steps.body:
A type alias can declare type parameters after its name, and each use fills them in, like arguments to a function:

```typescript
type ApiResponse<T> = { data: T; fetchedAt: string };

const greeting: ApiResponse<string> = { data: "Hello", fetchedAt: "2026-10-01T09:00:00Z" };
console.log(greeting.data.length); // 5
```

TypeScript doesn't infer a type's arguments from the value you assign, so `ApiResponse` written alone is an error: TS2314, `Generic type 'ApiResponse' requires 1 type argument(s)`. A default fixes that. With `type Envelope<T = unknown>`, writing `Envelope` alone means `Envelope<unknown>`. `unknown` makes a safe default, because code has to check the value before it uses it.

Interfaces take type parameters the same way, and their methods can use them:

```typescript types
interface Repository<T> {
  get(id: string): T | undefined;
  list(): T[];
}
```

To build values of a generic type, write a generic function that returns it. Each call infers `T` from its arguments, so callers never have to write it.

examples.code:
type ApiResponse<T> = { data: T; fetchedAt: string };
type User = { id: number; name: string };

function respond<T>(data: T): ApiResponse<T> {
  return { data, fetchedAt: "2026-10-01T09:00:00Z" };
}

const ada: User = { id: 1, name: "Ada" };
const users: User[] = [ada, { id: 2, name: "Grace" }];

const one = respond(ada);
//    ^? const one: ApiResponse<User>
const all = respond(users);
//    ^? const all: ApiResponse<User[]>

console.log(`${one.data.name} at ${one.fetchedAt}`);
console.log(`${all.data.length} users: ${all.data.map((u) => u.name).join(", ")}`);

type Page<T> = { items: T[]; nextCursor: string | null };
type Envelope<T = unknown> = { status: number; body: T };

const first: Page<string> = { items: ["Mug", "Kettle"], nextCursor: "c2" };
const last: Page<string> = { items: ["Teapot"], nextCursor: null };
const ok: Envelope<Page<string>> = { status: 200, body: first };
const failed: Envelope = { status: 500, body: "Server error" };
//    ^? const failed: Envelope<unknown>

for (const page of [first, last]) {
  console.log(`${page.items.join(", ")} (next: ${page.nextCursor ?? "none"})`);
}
console.log(`${ok.status}: ${ok.body.items.length} items`);
if (typeof failed.body === "string") {
  console.log(`${failed.status}: ${failed.body}`);
}

interface Repository<T> {
  get(id: string): T | undefined;
  list(): T[];
}

type Book = { id: string; title: string };
type Member = { id: string; name: string };

function arrayRepo<T extends { id: string }>(items: readonly T[]): Repository<T> {
  return {
    get: (id) => items.find((item) => item.id === id),
    list: () => [...items],
  };
}

function report<T>(label: string, repo: Repository<T>, show: (item: T) => string): void {
  console.log(`${label}: ${repo.list().map(show).join(", ")}`);
}

const bookList: Book[] = [
  { id: "b1", title: "Dune" },
  { id: "b2", title: "Emma" },
];
const books = arrayRepo(bookList);
//    ^? const books: Repository<Book>
const members = arrayRepo<Member>([{ id: "m1", name: "Ada" }]);

report("Books", books, (b) => b.title);
report("Members", members, (m) => m.name);
console.log(books.get("b2")?.title ?? "no such book");
console.log(books.get("b9")?.title ?? "no such book");

