practice.solution:
export type Page<T> = { items: T[]; nextCursor: string | null };

export function paginate<T>(items: readonly T[], pageSize: number, page: number): Page<T> {
  const start = (page - 1) * pageSize;
  const end = start + pageSize;
  return {
    items: items.slice(start, end),
    nextCursor: end < items.length ? String(page + 1) : null,
  };
}

const tasks = ["plan sprint", "write spec", "review PR", "fix login", "add tests", "deploy", "update docs"];

const first = paginate(tasks, 3, 1);
console.log(`Page 1: ${first.items.join(", ")} (next: ${first.nextCursor ?? "none"})`);
const third = paginate(tasks, 3, 3);
console.log(`Page 3: ${third.items.join(", ")} (next: ${third.nextCursor ?? "none"})`);

