steps.body:
A class takes type parameters after its name, and its fields and methods use them. Keep the state in JavaScript `#private` fields with a type, so only the class can touch it:

```typescript
class Box<T> {
  #value: T;

  constructor(value: T) {
    this.#value = value;
  }

  get(): T {
    return this.#value;
  }
}

const box = new Box(42);
//    ^? const box: Box<number>
console.log(box.get() + 1); // 43
```

`new Box(42)` infers `T` from the constructor's argument, the way a call to a generic function does. When the constructor takes nothing of type `T`, there's nothing to infer from, and `T` becomes `unknown`, so every value you get back would need narrowing before use. Pass the type argument yourself instead, as in `new Stack<string>()`.

A class can have several type parameters, and constraints work on them just as on functions.

examples.code:
class Stack<T> {
  #items: T[] = [];

  push(x: T): void {
    this.#items.push(x);
  }

  pop(): T | undefined {
    return this.#items.pop();
  }

  peek(): T | undefined {
    return this.#items.at(-1);
  }
}

const undo = new Stack<string>();
undo.push("bold title");
undo.push("delete line");
console.log(`Undo: ${undo.pop()}`);
console.log(`Undo: ${undo.pop()}`);
console.log(`Next undo: ${undo.peek() ?? "nothing left"}`);

const zoom = new Stack<number>();
zoom.push(100);
zoom.push(150);
const level = zoom.pop();
//    ^? const level: number | undefined
console.log(`Zoomed out from ${level}% to ${zoom.peek() ?? 100}%`);

class TtlCache<K, V> {
  #entries = new Map<K, { value: V; expiresAt: number }>();
  #ttlMs: number;
  #now: () => number;

  constructor(ttlMs: number, now: () => number) {
    this.#ttlMs = ttlMs;
    this.#now = now;
  }

  set(key: K, value: V): void {
    this.#entries.set(key, { value, expiresAt: this.#now() + this.#ttlMs });
  }

  get(key: K): V | undefined {
    const entry = this.#entries.get(key);
    if (entry === undefined) return undefined;
    if (this.#now() >= entry.expiresAt) {
      this.#entries.delete(key);
      return undefined;
    }
    return entry.value;
  }
}

let fakeNow = 0;
const rates = new TtlCache<string, number>(60_000, () => fakeNow);

rates.set("EUR", 1.08);
console.log(`At 0 ms: ${rates.get("EUR") ?? "expired"}`);
fakeNow = 59_999;
console.log(`At 59999 ms: ${rates.get("EUR") ?? "expired"}`);
fakeNow = 60_000;
console.log(`At 60000 ms: ${rates.get("EUR") ?? "expired"}`);
console.log(`GBP: ${rates.get("GBP") ?? "never cached"}`);

class InMemoryRepo<T extends { id: string }> {
  #items = new Map<string, T>();

  save(item: T): void {
    this.#items.set(item.id, item);
  }

  get(id: string): T | undefined {
    return this.#items.get(id);
  }

  list(): T[] {
    return [...this.#items.values()];
  }
}

type Customer = { id: string; name: string; plan: "free" | "pro" };

const customers = new InMemoryRepo<Customer>();
customers.save({ id: "c1", name: "Ada", plan: "pro" });
customers.save({ id: "c2", name: "Ben", plan: "free" });
customers.save({ id: "c1", name: "Ada", plan: "free" });

for (const c of customers.list()) {
  console.log(`${c.id}: ${c.name} (${c.plan})`);
}
const c3 = customers.get("c3");
//    ^? const c3: Customer | undefined
console.log(c3 ? c3.name : "no customer c3");

examples.explanation:
`T extends { id: string }` lets `save` read `item.id`, and `new InMemoryRepo<Customer>()` keeps the whole `Customer` type for `get` and `list`, so `c.plan` is there to print. The items live in a `Map` keyed by id, so saving `c1` again replaces it. A `Map` keeps each key where it was first added, so `c1` still lists first, now on the free plan. A type without an `id` doesn't fit the constraint:

```typescript error
class InMemoryRepo<T extends { id: string }> {
  #items = new Map<string, T>();

  list(): T[] {
    return [...this.#items.values()];
  }
}

const notes = new InMemoryRepo<{ text: string }>();
console.log(notes.list().length);
```

The Interfaces, Abstract Classes, and Dependency Injection lesson has a class like this implement a `Repository` interface.

