import { EventEmitter } from "node:events";

type Order = { id: string; totalCents: number };

type OrderEvents = {
  created: [order: Order];
  cancelled: [id: string, reason: string];
};

const events = new EventEmitter<OrderEvents>();

events.on("created", (order) => {
  //                  ^? (parameter) order: Order
  console.log(`Created ${order.id}: $${(order.totalCents / 100).toFixed(2)}`);
});
events.on("cancelled", (id, reason) => {
  console.log(`Cancelled ${id}: ${reason}`);
});

events.emit("created", { id: "o1", totalCents: 1299 });
events.emit("created", { id: "o2", totalCents: 450 });
events.emit("cancelled", "o1", "out of stock");

import { EventEmitter } from "node:events";

type OrderEvents = {
  created: [id: string];
  cancelled: [id: string, reason: string];
};

const events = new EventEmitter<OrderEvents>();
events.on("cancelled", (id, reason) => {
  console.log(`Cancelled ${id}: ${reason}`);
});

events.emit("cancelled", "o1");

examples.explanation:
The `cancelled` tuple has two elements, so `emit("cancelled", ...)` takes the event name plus two arguments. The message counts the name too, which is why it expects 3. Without the type argument, the same `emit` compiles, and the listener runs without its reason:

```typescript
import { EventEmitter } from "node:events";

const events = new EventEmitter();
events.on("cancelled", (id, reason) => {
  console.log(`Cancelled ${id}: ${reason}`); // Cancelled o1: undefined
});
events.emit("cancelled", "o1");
```

One gap remains with the typed version: Node's types still accept an event name that isn't in the map. A listener for a misspelled `"canceled"` compiles, gets arguments typed `any`, and never runs. The map is the one place each name is spelled, so check names against it.

