import { EventEmitter } from "node:events";

export type OrderEvents = {
  placed: [id: string, totalCents: number];
  shipped: [id: string, carrier: string];
};

export const bus = new EventEmitter<OrderEvents>();

bus.on("placed", (id, totalCents) => {
  console.log(`Placed ${id}: $${(totalCents / 100).toFixed(2)}`);
});
bus.on("shipped", (id, carrier) => {
  console.log(`Shipped ${id} with ${carrier}`);
});

bus.emit("placed", "o1", 1299);
bus.emit("placed", "o2", 4500);
bus.emit("shipped", "o1", "UPS");
